/**
 * @method
 * @name checkValue
 * @description // 그리드에서 클릭 row의 변수셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function() {
    if (txb_isur_cd.getValue() !== txb_isurcd.getValue()) {
        await $c.win.alert("회사 선택후 벌점부과현황을 조회후에 입력처리가 가능합니다.");
        txb_isur_cd.focus();
        return false;
    }
    if (edt_impost_dd.getValue() === "" && edt_design_grace_fix_dd.getValue() === "") {
        await $c.win.alert("벌점부과일or지정유예 결정일은 필수입니다.");
        return false;
    }

    // 벌점 부과 경우
    if (edt_impost_dd.getValue() !== "") {
        if (txb_pnlt.getValue() === "") {
            await $c.win.alert("벌점을 입력하십시오");
            txb_pnlt.focus();
            return false;
        }
        if (txb_pnlt.getValue() !== '' && scwin.isNumJum(txb_pnlt.getValue()) === false) {
            await $c.win.alert("벌점은 숫자만 입력가능합니다.");
            txb_pnlt.focus();
            return false;
        }
        if (txb_sanctn_amt.getValue() === "") {
            await $c.win.alert("0 이상의 금액을 입력하셔야 합니다.");
            txb_sanctn_amt.focus();
            return false;
        }
        if (txb_sanctn_amt.getValue() !== '' && $c.ut.isNum(txb_sanctn_amt.getValue()) === false) {
            await $c.win.alert("숫자만 입력가능합니다.");
            txb_sanctn_amt.focus();
            return false;
        }
    }

    // 지정유예의 경우
    if (edt_design_grace_fix_dd.getValue() !== "") {
        if (txb_DESIGN_GRACE_PNLT.getValue() === "") {
            await $c.win.alert("지정유예 벌점을 입력하십시오");
            txb_DESIGN_GRACE_PNLT.focus();
            return false;
        }
        if (cmb_designGraceRsnCd.getValue() === "") {
            await $c.win.alert("지정유예 사유를 입력하십시오");
            cmb_designGraceRsnCd.focus();
            return false;
        }
        if (edt_gracepd_end_dd.getValue() === "") {
            await $c.win.alert("유예기간 만료일은 필수입니다.");
            edt_gracepd_end_dd.focus();
            return false;
        }
        if (txb_DESIGN_GRACE_PNLT.getValue() !== '' && scwin.isNumJum(txb_DESIGN_GRACE_PNLT.getValue()) === false) {
            await $c.win.alert("지정유예 벌점은 숫자만 입력가능합니다.");
            txb_DESIGN_GRACE_PNLT.focus();
            return false;
        }
    }
    if (edt_impost_dd.getValue() !== "" || edt_design_grace_fix_dd.getValue() !== "") {
        if (edt_rsnoccr_dd.getValue() === "") {
            await $c.win.alert("사유발생일을 입력하십시오");
            edt_rsnoccr_dd.focus();
            return false;
        }
        if (cmb_ImpostRsn.getValue() === "") {
            await $c.win.alert("벌점(제재금)부과사유를 선택하십시오");
            cmb_ImpostRsn.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name isNumJum
 * @description is Num Jum 처리
 * @param {*} sVal sVal
 * @returns {void}
 * @hidden N
 */
scwin.isNumJum = function(sVal) {
    if (('0' < sVal) || ('9' > sVal) || ('.' === sVal)) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name insert
 * @description 벌점 입력
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    if (await scwin.checkValue() === false) {
        return;
    }
    dts_Pnlt_Input.insertRow();
    dts_Pnlt_Input.setCellData(1, "ISUR_CD", txb_isurcd.getValue());
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_DD", edt_impost_dd.getValue());
    dts_Pnlt_Input.setCellData(1, "RSN_OCCR_DD", edt_rsnoccr_dd.getValue());
    //        dts_Pnlt_Input.NameValue(1,"PNLT_IMPOST_TP_CD") = getObjectValue(cmb_ImpostTp) ;
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_RSN_CD", cmb_ImpostRsn.getValue());
    dts_Pnlt_Input.setCellData(1, "VIOL_SANCTN_AMT", txb_sanctn_amt.getValue());
    dts_Pnlt_Input.setCellData(1, "PNLT", txb_pnlt.getValue());
    dts_Pnlt_Input.setCellData(1, "LD_MKT_TP", js_market);
    dts_Pnlt_Input.setCellData(1, "CONFRMR_EMP_NO", js_emp_no);
    dts_Pnlt_Input.setCellData(1, "REMK", txa_remk.getValue());
    dts_Pnlt_Input.setCellData(1, "DESIGN_GRACE_FIX_DD", edt_design_grace_fix_dd.getValue());
    dts_Pnlt_Input.setCellData(1, "GRACEPD_END_DD", edt_gracepd_end_dd.getValue());
    dts_Pnlt_Input.setCellData(1, "DESIGN_GRACE_RSN_CD", cmb_designGraceRsnCd.getValue());
    dts_Pnlt_Input.setCellData(1, "DESIGN_GRACE_PNLT", txb_DESIGN_GRACE_PNLT.getValue());
    let actTp = 0;
    let alertMsg = "벌점입력";
    if (edt_impost_dd.getValue() === "") {
        actTp = 1;
        alertMsg = "지정유예";
    }
    let vAnswer = confirm(alertMsg + ' 처리를 하시겠습니까?');
    if (vAnswer === true) {
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Pnlt_Input",
            action : "/PenaltyImposition.do",
            ref : "dts_Pnlt_Input",
            target : "trs_Pnlt_Input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(row) {
    const com_nm = dts_pnltsat_info.getCellData(1, "CO_NM");
    const occr_dd = dts_pnlt_history.getCellData(row, "RSN_OCCR_DD");
    let vAnswer = confirm(com_nm + '(사유발생일:' + occr_dd + ') 항목을 삭제처리 하시겠습니까?');
    if (vAnswer === true) {
        // 가우스헤더 셋팅
        dts_Pnlt_Input.insertRow();
        dts_Pnlt_Input.setCellData(1, "CONFRMR_EMP_NO", js_emp_no);
        dts_Pnlt_Input.setCellData(1, "ISUR_CD", dts_pnlt_history.getCellData(row, "ISUR_CD"));
        dts_Pnlt_Input.setCellData(1, "PNLT_SEQ", dts_pnlt_history.getCellData(row, "PNLT_SEQ"));
        dts_Pnlt_Input.setCellData(1, "RSN_OCCR_DD", dts_pnlt_history.getCellData(row, "RSN_OCCR_DD"));
        dts_Pnlt_Input.setCellData(1, "LD_MKT_TP", js_market);
        dts_Pnlt_Input.setCellData(1, "GRACEPD_END_DD", dts_pnlt_history.getCellData(row, "GRACEPD_END_DD")); // 일정에서 삭제하기 위해 필요.
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Pnlt_Input",
            action : "/PenaltyImposition.do",
            ref : "dts_Pnlt_Input",
            target : "trs_Pnlt_Input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name clear
 * @description 입력항목 clear
 * @returns {void}
 * @hidden N
 */
scwin.clear = function() {
    edt_impost_dd.setValue("");
    edt_rsnoccr_dd.setValue("");
    cmb_ImpostRsn.setValue("");
    txb_sanctn_amt.setValue("");
    txb_pnlt.setValue("");
    txa_remk.setValue("");
};

/**
 * @method
 * @name check_design_grace_fix_dd
 * @description 지정유예사유를 수정한 경우 지정유예 결정일이 있어야함.
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check_design_grace_fix_dd = async function(obj) {
    if (obj.getValue() !== '') {
        if (edt_design_grace_fix_dd.getValue() === '') {
            obj.setValue('');
            await $c.win.alert('지정유예결정일을 먼저 입력하셔야 합니다.');
        }
    }
};

/**
 * @method
 * @name checkGraceInfo
 * @description gubunPNLT  1:벌점(제재금)부과일, 2:지정유예걸정일이 입력된 경우.
 * @param {*} gubunPNLT gubunPNLT
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkGraceInfo = async function(gubunPNLT) {
    if (gubunPNLT === '1') {
        if (edt_impost_dd.getValue() !== '') {
            edt_design_grace_fix_dd.setValue('');
            txb_DESIGN_GRACE_PNLT.setDisabled(true);
            txb_DESIGN_GRACE_PNLT.setValue('');
            cmb_designGraceRsnCd.setDisabled(true);
            cmb_designGraceRsnCd.setSelectedIndex(0);
            edt_gracepd_end_dd.setDisabled(true);
            edt_gracepd_end_dd.setValue('');
            txb_pnlt.setDisabled(false);
            txb_sanctn_amt.setDisabled(false);
        }
    } else {
        if (edt_design_grace_fix_dd.getValue() !== '') {
            edt_impost_dd.setValue('');
            txb_pnlt.setDisabled(true);
            txb_pnlt.setValue('');
            txb_sanctn_amt.setValue('');
            txb_sanctn_amt.setDisabled(true);
            txb_DESIGN_GRACE_PNLT.setDisabled(false);
            cmb_designGraceRsnCd.setDisabled(false);
            edt_gracepd_end_dd.setDisabled(false);
            await scwin.getWorkdayIn6Months();
        }
    }
};

/**
 * @method
 * @name getWorkdayIn6Months
 * @description get Workday In6 Months 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getWorkdayIn6Months = async function() {
    const sbmOptions = {
        id : "sbm_dts_workday_in_6_months",
        action : "/PenaltyImposition.do",
        ref : "",
        target : "dts_workday_in_6_months=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name filedown
 * @description 1개선계획서파일 or  2주의조치내역 다운로드
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(ver) {
    let tIsur_cd = '';
    let tSeq = '';
    let tGubun = '';
    // var vRegDd = dts_imprschdl_file.NameString(1,"IMPR_REG_DD");
    if (ver === "1") {
        tIsur_cd = dts_imprschdl_file.getCellData(1, "ISUR_CD");
        tSeq = dts_imprschdl_file.getCellData(1, "SEQ");
        tGubun = "60";
    } else {
        tIsur_cd = dts_CautnActDtl.getCellData(1, "ISUR_CD");
        tSeq = dts_CautnActDtl.getCellData(1, "SEQ");
        tGubun = "61";
    }
    const link = "/filedownload.do?" + "ISUR_CD=" + tIsur_cd + "&SEQ=" + tSeq + "&gubun=" + tGubun + "&SCREN_ID=" + 'ULDSTF35109.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
    location.href = encodeURI(link);
};

/**
 * @method
 * @name deleteCautnActDtl
 * @description delete Cautn Act Dtl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteCautnActDtl = async function() {
    let vAnswer = confirm('주의조치 내역을 삭제처리 하시겠습니까?');
    if (vAnswer === true) {
        dts_CautnActDtl_input.insertRow();
        dts_CautnActDtl_input.setCellData(1, "ISUR_CD", dts_CautnActDtl.getCellData(1, "ISUR_CD"));
        dts_CautnActDtl_input.setCellData(1, "SEQ", dts_CautnActDtl.getCellData(1, "SEQ"));
        dts_CautnActDtl_input.setCellData(1, "EMP_NO", js_emp_no);
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Pnlt_Input",
            action : "/PenaltyImposition.do",
            ref : "dts_CautnActDtl_input",
            target : "trs_Pnlt_Input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name dts_ImpostRsn_OnLoadCompleted
 * @description dts_ImpostRsn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ImpostRsn_OnLoadCompleted = function(rowcount) {
    dts_ImpostRsn.UseFilter = true;
    dts_ImpostRsn.Filter();
    dts_ImpostRsn.sort("VALUE", 0);
    // dts_ImpostRsn.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_ImpostRsn_OnFilter
 * @description 코스닥용 벌점부과사유 보여주기
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ImpostRsn_OnFilter = function(row) {
    // 코스닥용 벌점부과사유 보여주기
    if (dts_ImpostRsn.getCellData(row, "value") === '1' ||
        dts_ImpostRsn.getCellData(row, "value") === '2' ||
        dts_ImpostRsn.getCellData(row, "value") === '3' ||
        dts_ImpostRsn.getCellData(row, "value") === '4' ||
        dts_ImpostRsn.getCellData(row, "value") === '6' ||
        dts_ImpostRsn.getCellData(row, "value") === '7' ||
        dts_ImpostRsn.getCellData(row, "value") === '8' ||
        dts_ImpostRsn.getCellData(row, "value") === '9' ||
        dts_ImpostRsn.getCellData(row, "value") === 'B' ||
        dts_ImpostRsn.getCellData(row, "value") === 'C' ||
        dts_ImpostRsn.getCellData(row, "value") === '') {
        if (dts_ImpostRsn.getCellData(row, "value") === '4') {
            dts_ImpostRsn.setCellData(row, "text", '개선(이행)보고서미제출');
        }
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name dts_ImpostGraceRsn_OnLoadCompleted
 * @description dts_ImpostGraceRsn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
