 */
scwin.dts_ImpostGraceRsn_OnLoadCompleted = function(rowcount) {
    dts_ImpostGraceRsn.UseFilter = true;
    dts_ImpostGraceRsn.Filter();
    dts_ImpostGraceRsn.sort("VALUE", 0);
    // dts_ImpostGraceRsn.sort(); // W-Craft 주석처리

};

/**
