/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    txb_isurcd.hide(); // 히든처리!
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    await scwin.setCode();

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_Pnlt_Input",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Pnlt_Input=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 가우스헤더 셋팅
    const sbmOptions2 = {
        id : "sbm_dts_CautnActDtl",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_CautnActDtl=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_CautnActDtl_input",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_CautnActDtl_input=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.getParentValue();
};

